from nlib import *
S=[]
def O(id,title,kind,sc,sm,b,d,e,f,dy,par,made=(),proc=(),mesh=None,hs=None,sec="23.1",kn=(),rel=(),cert="C1",oq=None,tmpl="anatomy",mol=None):
    S.append(N(id,title,kind,tmpl,sc,sm,b,d,e,f,dy,par=par,made=made,proc=proc,mesh=mesh,hs=hs,refs=[("ANP",sec)],kn=kn,rel=rel,cert=cert,oq=oq,mol=mol))
DG="digestive_system"; DK=("digestion_renal",)
EP=["epithelial_tissue"]; SM=["smooth_muscle_tissue"]
O("mouth_pharynx","Mouth, teeth and pharynx","structure",0.15,"Where digestion starts: chewing, saliva and swallowing.","Teeth grind food and saliva begins breaking down starch. Your tongue pushes the food to the throat to swallow.","Salivary glands release about 1-1.5 L of saliva daily containing amylase and lipase. Swallowing is a reflex coordinated by the brainstem.","Swallowing has oral, pharyngeal and esophageal phases; the epiglottis diverts food from the airway; adults have 32 teeth, and enamel is ≈ 96% mineral (hydroxyapatite).",[("Adult teeth","32"),("Saliva per day","≈ 1-1.5 L"),("Enamel mineral","≈ 96%")],"Tooth enamel is the hardest substance in the human body.",[DG],EP+["skeletal_muscle_tissue"],["digestion"],kn=DK,sec="23.3")
O("esophagus","Esophagus","organ",0.25,"A muscular tube that carries swallowed food to the stomach.","The food pipe pushes your food down by waves of squeezing, so you can even swallow upside down.","Upper third is skeletal muscle, lower third smooth muscle, with sphincters at both ends.","Peristalsis driven by the vagus and enteric plexuses; lower esophageal sphincter prevents reflux; stratified squamous epithelium.",[("Length","≈ 25 cm"),("Transit time","≈ 5-10 s")],"Astronauts can swallow in zero gravity because muscles, not gravity, move food.",[DG],EP+SM+["skeletal_muscle_tissue"],["digestion"],mesh="esophagus",kn=DK,sec="23.3")
O("stomach","Stomach","organ",0.25,"A stretchy muscular sac that churns food with acid and enzymes.","The stomach mixes food into a thick soup called chyme and starts breaking down protein.","It can hold about 1-1.5 L; gastric juice has a pH around 1.5-3.5, strong enough to kill most microbes.","Parietal cells secrete HCl and intrinsic factor, chief cells release pepsinogen, G cells secrete gastrin; mucus-bicarbonate layer protects the wall; emptying ≈ 2-4 h.",[("Capacity","≈ 1-1.5 L (can expand)"),("Acid pH","≈ 1.5-3.5"),("Emptying","≈ 2-4 h")],"The stomach lining replaces itself every few days, and the lining cells are renewed so fast it avoids digesting itself.",[DG],EP+SM+["connective_tissue_loose"],["digestion"],mesh="stomach",kn=DK,sec="23.4")
O("gastric_pits","Gastric pits and glands","structure",0.0003,"Tiny pits in the stomach lining that release acid, enzymes and mucus.","The stomach wall is dotted with millions of little pits that pour out digestive juices.","Different cells in each gland make acid, enzymes, mucus and hormones.","Parietal cells (H+/K+ ATPase), chief cells (pepsinogen), mucous neck cells, enteroendocrine G cells; stem cells at the isthmus.",[("Pits","≈ 3-4 million"),("Pit depth","≈ 0.3 mm")],"The proton pump in these cells can create a 1,000,000-fold H+ gradient.",["stomach"],EP,["digestion"],hs=("stomach",(0.04,0.0,0.03),"Gastric pits"),kn=DK,sec="23.4")
O("small_intestine","Small intestine","organ",6.0,"A long coiled tube where most digestion and absorption of nutrients happen.","This is where most food becomes usable nutrients, absorbed through a huge folded lining.","It has three parts: duodenum, jejunum and ileum. Bile and pancreatic enzymes enter the duodenum.","Circular folds, villi and microvilli amplify surface ≈ 600-fold; brush border enzymes finish digestion; segmentation and migrating motor complexes mix and move contents.",[("Length","≈ 3-6 m"),("Diameter","≈ 2.5-3 cm"),("Effective area","≈ 30-40 m²")],"Despite the name 'small', it is the longest part of your digestive tube.",[DG],EP+SM,["digestion"],mesh="small_intestine",kn=DK,sec="23.5")
O("villi","Intestinal villi","structure",0.001,"Finger-like projections that greatly increase the intestine's absorption area.","Villi are tiny fingers covering the inner wall, soaking up nutrients.","Each villus has capillaries for sugars and amino acids and a lymph vessel (lacteal) for fats.","Enterocytes carry microvilli (brush border) ≈ 1 µm tall; crypts of Lieberkühn house stem cells; epithelial turnover ≈ 3-5 days.",[("Height","≈ 0.5-1 mm"),("Density","≈ 10-40 per mm²")],"The intestinal lining is replaced every 3 to 5 days, one of the fastest turnover rates in the body.",["small_intestine"],["enterocyte","epithelial_tissue"],["digestion"],hs=("small_intestine",(0.0,0.0,0.01),"Villi"),kn=DK,sec="23.5")
O("large_intestine","Large intestine (colon)","organ",1.5,"The wide tube that absorbs water and salts and houses most gut microbes.","The large intestine turns leftovers into stool and hosts trillions of helpful bacteria.","It includes cecum, colon and rectum. Gut microbes ferment fiber into useful fatty acids.","Colonic transit ≈ 20-50 h; microbial fermentation gives short-chain fatty acids (acetate, propionate, butyrate) used by colonocytes; microbial density ≈ 10^11-10^12 per gram.",[("Length","≈ 1.5 m"),("Water absorbed","≈ 1-1.5 L/day"),("Microbes","≈ 4×10^13 (whole body)")],"About half of stool dry weight is bacterial biomass.",[DG],EP+SM,["digestion"],mesh="large_intestine",kn=DK,sec="23.5")
O("microbiome","Gut microbiome","structure",1.5,"The community of trillions of microbes living mainly in the large intestine.","Your gut hosts bacteria, archaea, fungi and viruses that help digest fiber, train the immune system and make vitamins.","Their composition varies between people and over time, shaped by diet, age and environment.","Metagenomic sequencing reveals ≈ 10^3 species per person; causal links to obesity, mood or disease are actively researched, and many associations remain correlational.",[("Microbial cells","≈ 3.8×10^13"),("Genes (microbial)","≈ 10^6-10^7")],"The ratio of microbial to human cells is closer to 1:1 than the older 10:1 estimate.",["large_intestine"],[],["digestion"],kn=("bacteria_archaea",),cert="C3",oq=["Which microbiome features cause (rather than merely correlate with) health effects?","How reliably can microbiome interventions treat disease?"],sec="23.5")
O("liver","Liver","organ",0.2,"The largest internal organ, which processes nutrients, makes bile and detoxifies the blood.","The liver is a chemical factory that cleans blood, stores energy and makes bile to digest fats.","It receives blood both from the gut (portal vein) and from the heart (hepatic artery), and can regrow after partial removal.","Performs >500 functions: glycogen storage, gluconeogenesis, albumin and clotting factor synthesis, urea cycle, cytochrome P450 drug metabolism and bile acid production.",[("Mass","≈ 1.4-1.8 kg"),("Blood flow","≈ 1.5 L/min"),("Hepatocytes","≈ 2×10^11")],"The liver can regenerate to full size from as little as a quarter of its mass.",[DG],["hepatocyte","connective_tissue_loose"],["digestion"],mesh="liver",kn=DK,sec="23.6")
O("liver_lobule","Liver lobule","structure",0.001,"A hexagonal unit of liver tissue where blood is processed.","Blood flows through each lobule, passing liver cells that clean it.","Blood flows from the corners (portal triads) toward a central vein.","Sinusoids, Kupffer cells, stellate cells; zonation (periportal to pericentral) specializes metabolism.",[("Width","≈ 1-2 mm"),("Number","≈ 10^5")],"Each lobule is about as wide as a grain of sand.",["liver"],["hepatocyte"],["digestion"],hs=("liver",(0.02,0.0,0.02),"Liver lobule"),kn=DK,sec="23.6")
O("gallbladder","Gallbladder","organ",0.08,"A small sac that stores and concentrates bile.","The gallbladder holds bile until fatty food arrives, then squeezes it into the intestine.","Bile helps break fats into tiny droplets.","CCK triggers gallbladder contraction and sphincter of Oddi relaxation; bile concentrates 5-10×; cholesterol stones are common.",[("Capacity","≈ 30-50 mL"),("Bile stored","≈ 50 mL")],"People can live normally without a gallbladder.",[DG],EP+SM,["digestion"],mesh="gallbladder",kn=DK,sec="23.6")
O("pancreas","Pancreas","organ",0.15,"A gland that makes digestive enzymes and the hormones insulin and glucagon.","The pancreas does two jobs: it sends enzymes to the intestine and hormones to the blood.","Most of it (acinar tissue) makes enzymes; small clusters of cells called islets make hormones.","Exocrine secretion (≈ 1-1.5 L/day) includes trypsinogen, amylase, lipase and bicarbonate; endocrine islets contain alpha, beta, delta cells.",[("Mass","≈ 80-100 g"),("Enzyme juice","≈ 1-1.5 L/day")],"The name pancreas comes from Greek for 'all flesh'.",[DG,"endocrine_system"],["epithelial_tissue","connective_tissue_loose"],["digestion","hormone_signaling"],mesh="pancreas",sec="23.6",kn=("endocrine_physiology",))
O("pancreatic_islets","Pancreatic islets","structure",0.0002,"Clusters of cells in the pancreas that make insulin and glucagon.","About a million tiny islands of cells that monitor your blood sugar.","Beta cells release insulin to lower blood sugar; alpha cells release glucagon to raise it.","≈ 1-2% of pancreatic mass; beta cells ≈ 50-70% of islet; glucose sensing via GLUT/glucokinase and K-ATP channels triggers insulin exocytosis.",[("Islets","≈ 10^6"),("Diameter","≈ 0.1-0.3 mm")],"Islets make up only about 1-2% of the pancreas.",["pancreas"],[],["hormone_signaling"],hs=("pancreas",(0.03,0.0,0.0),"Islets of Langerhans"),sec="17.9",kn=("endocrine_physiology",),mol=["glucose_beta"])
# Urinary
UR="urinary_system"
for sd,sn in (("l","Left"),("r","Right")):
    O(f"kidney_{sd}",f"{sn} kidney","organ",0.11,f"The {'left' if sd=='l' else 'right'} kidney filters blood and makes urine.","Kidneys are bean-shaped organs that clean your blood and control water, salt and acid levels.","Each has about a million nephrons. Blood enters via the renal artery, filtered fluid becomes urine collected in the renal pelvis.","Receives ≈ 20-25% of cardiac output; GFR ≈ 120 mL/min; also secretes renin, erythropoietin and activates vitamin D (calcitriol).",[("Length","≈ 11 cm"),("Mass","≈ 150 g"),("Nephrons","≈ 10^6")],"Each kidney is only about the size of a fist, but together they handle a fifth of your blood flow.",[UR],["epithelial_tissue","smooth_muscle_tissue","connective_tissue_loose"],["urine_formation"],mesh=f"kidney_{sd}",kn=DK,sec="25.3")
K="kidney_r"
for i,t,sc,sm,b,d,e,at,lab in [
("renal_cortex","Renal cortex",0.01,"The outer layer of the kidney holding the filters.","The outer shell where blood is first filtered.","It contains glomeruli and most of the tubules.","Cortical labyrinth and medullary rays; ≈ 85% of nephrons are cortical.",(-0.025,0.0,0.0),"Cortex"),
("renal_medulla","Renal medulla",0.03,"Inner region with cone-shaped pyramids that concentrate urine.","The inner part drains urine and concentrates it.","Pyramids of collecting ducts and loops of Henle.","Osmotic gradient from ≈ 300 to ≈ 1200 mOsm/kg establishes countercurrent multiplication.",(-0.01,0.0,0.0),"Medulla"),
("renal_pelvis","Renal pelvis",0.02,"The funnel where urine collects before flowing to the ureter.","Urine collects here and then flows down the ureter.","Minor and major calyces feed into it.","Peristalsis of calyces and pelvis propels urine; urothelium resists toxicity of urine.",(0.015,0.0,0.0),"Renal pelvis"),
]:
    O(i,t,"structure",sc,sm,b,d,e,[("Role",sm.rstrip('.'))],"Only about a fifth of the kidney's blood flow ends up as filtrate." if i!="renal_pelvis" else "A kidney stone often gets stuck where the pelvis meets the ureter.",[K],["epithelial_tissue"],["urine_formation"],hs=(K,at,lab),kn=DK,sec="25.3")
O("nephron","Nephron","structure",0.05,"The kidney's microscopic filtering and processing unit.","Each nephron filters blood and then takes back the water and nutrients your body wants to keep.","It consists of a glomerulus, a long tubule with several regions, and drains into a collecting duct.","Segments: Bowman's capsule, proximal convoluted tubule (≈ 65% reabsorption), loop of Henle, distal tubule, connecting tubule; juxtaglomerular apparatus regulates GFR via tubuloglomerular feedback.",[("Length","≈ 3-5 cm tubule (up to ~5)"),("Per kidney","≈ 10^6")],"If all the kidney tubules were stretched out, they would be roughly 80 km long.",["kidney_l",K],["epithelial_tissue"],["urine_formation"],hs=(K,(-0.02,0.01,0.0),"Nephron"),kn=DK,sec="25.4",tmpl="micro")
NP="nephron"
for i,t,sm,b,d,e,at,lab in [
("glomerulus","Glomerulus","A tuft of capillaries where blood plasma is filtered.","Blood is pushed against a super-fine sieve; water and small molecules pass, cells and big proteins stay.","Three layers: fenestrated endothelium, basement membrane, podocyte slit diaphragms.","Filtration fraction ≈ 20%; filtration pressure ≈ 10 mmHg net; podocytes' nephrin slit-diaphragm restricts albumin.",(0.0,0.015,0.0),"Glomerulus"),
("proximal_tubule","Proximal convoluted tubule","The first long tube segment that reclaims most water, salt and all glucose.","Most of what you need (sugar, water, salts) is taken back here.","Brush border and abundant mitochondria support active transport.","Na+-coupled transport (SGLT2 takes up glucose); ≈ 65% of Na+ and water reabsorbed; secretion of organic acids and bases.",(0.003,0.01,0.0),"Proximal tubule"),
("loop_of_henle","Loop of Henle","A hairpin that builds the salt gradient used to concentrate urine.","The loop of Henle dips into the kidney's inner zone, building a salty gradient so the body can make concentrated urine.","Descending limb is water-permeable, ascending thick limb pumps out salt (NKCC2).","Countercurrent multiplier; loop diuretics block NKCC2; vasa recta maintain gradient.",(0.0,-0.012,0.0),"Loop of Henle"),
("distal_tubule","Distal convoluted tubule","The fine-tuning segment that adjusts salt and calcium.","Hormones adjust the final salt and calcium balance here.","Aldosterone and PTH act on segments here.","NCC transporter (thiazide target); regulated by aldosterone and PTH; macula densa sensor.",(-0.003,0.01,0.0),"Distal tubule"),
("collecting_duct","Collecting duct","The final tube that gathers urine and sets its water content.","The last stop for adjusting urine's water content, controlled by the hormone ADH.","Water channels (aquaporin-2) are inserted when ADH is high, making urine concentrated.","Principal cells (ENaC, AQP2) and intercalated cells (acid-base); urea recycling in the inner medulla.",(0.006,0.0,0.0),"Collecting duct"),
]:
    O(i,t,"structure",0.01,sm,b,d,e,[("Role",sm.rstrip('.'))],"Urine concentration can swing about 24-fold, from roughly 50 to 1200 mOsm/kg." ,[NP],["epithelial_tissue"],["urine_formation"],hs=(NP,at,lab),kn=DK,sec="25.4" if i!="proximal_tubule" else "25.6",tmpl="micro")
O("ureters","Ureters","organ",0.28,"Two muscular tubes carrying urine from the kidneys to the bladder.","Waves of muscle squeeze urine down these thin tubes, even if you're lying down.","Peristalsis every 10 to 60 seconds pushes urine along.","Urothelium; three constrictions (pelviureteric junction, pelvic brim, vesicoureteric junction) are common stone-lodging sites.",[("Length","≈ 25-30 cm"),("Diameter","≈ 3-4 mm")],"They enter the bladder at an angle, forming a one-way valve.",[UR],["smooth_muscle_tissue","epithelial_tissue"],["urine_formation"],mesh="ureters",kn=DK,sec="25.2")
O("bladder","Urinary bladder","organ",0.12,"A stretchy muscular bag that stores urine.","The bladder fills like a balloon and signals when it's time to go.","It typically holds 400-600 mL, with the urge starting at about 200-300 mL.","Detrusor smooth muscle and transitional epithelium (urothelium); micturition reflex coordinated by sacral cord (S2-S4) and pontine micturition center; internal and external sphincters.",[("Capacity","≈ 400-600 mL"),("Urge threshold","≈ 200-300 mL")],"The bladder wall can stretch to many times its relaxed size without pressure rising much.",[UR],["smooth_muscle_tissue","epithelial_tissue"],["urine_formation"],mesh="bladder",kn=DK,sec="25.2")
O("urethra","Urethra","structure",0.2,"The tube that carries urine out of the body.","The final tube for urine. It is longer in males than in females.","Sphincters control release.","Female ≈ 4 cm, male ≈ 20 cm; the male urethra also carries semen.",[("Female length","≈ 4 cm"),("Male length","≈ 20 cm")],"Its length difference explains why urinary infections are more common in females.",[UR,"reproductive_system"],["smooth_muscle_tissue","epithelial_tissue"],["urine_formation"],kn=DK,sec="25.2")
# Endocrine
ED="endocrine_system"; EK=("endocrine_physiology",)
O("pituitary_gland","Pituitary gland","organ",0.012,"A pea-sized gland that controls many other hormone glands.","Called the master gland, it releases hormones controlling growth, stress, thyroid and reproduction.","The anterior lobe makes hormones like growth hormone and TSH; the posterior lobe releases oxytocin and ADH made in the hypothalamus.","Anterior lobe receives hypophyseal portal blood carrying releasing hormones; posterior is neural tissue releasing OT and AVP.",[("Mass","≈ 0.5 g"),("Hormones","≈ 8 major")],"It sits in a small bony pocket of the skull called the sella turcica.",[ED,"brain"],["epithelial_tissue","nervous_tissue"],["hormone_signaling"],hs=("brain",(0.0,-0.035,0.015),"Pituitary"),sec="17.3",kn=EK)
O("thyroid","Thyroid","organ",0.05,"A butterfly-shaped gland in the neck that sets the body's metabolic pace.","The thyroid releases hormones that control how fast your cells use energy.","It needs iodine to make thyroxine (T4) and triiodothyronine (T3).","TSH stimulates thyroglobulin iodination; T3 acts via nuclear thyroid hormone receptors; C cells secrete calcitonin.",[("Mass","≈ 20 g"),("Iodine content","≈ 10-15 mg")],"Iodine-deficiency can cause a swollen thyroid (goiter).",[ED],["epithelial_tissue","connective_tissue_loose"],["hormone_signaling"],mesh="thyroid",sec="17.4",kn=EK,mol=["thyroxine"])
O("parathyroid_glands","Parathyroid glands","organ",0.006,"Four tiny glands behind the thyroid that control blood calcium.","They monitor calcium in your blood and release a hormone to raise it when low.","Parathyroid hormone acts on bone, kidney and gut.","PTH release is controlled by the calcium-sensing receptor; PTH increases bone resorption, renal Ca2+ reabsorption and calcitriol synthesis.",[("Number","usually 4"),("Size","≈ 6 mm each")],"They were the last major organs identified in humans.",[ED],["epithelial_tissue"],["hormone_signaling","bone_remodeling"],sec="17.5",kn=EK)
O("adrenal_glands","Adrenal glands","organ",0.05,"Two glands atop the kidneys that release stress hormones.","They make adrenaline and cortisol, which help you respond to stress.","The outer cortex makes steroid hormones; the inner medulla makes adrenaline.","Zones: glomerulosa (aldosterone), fasciculata (cortisol), reticularis (androgens); medulla chromaffin cells secrete epinephrine in response to sympathetic input.",[("Mass (each)","≈ 4-5 g"),("Parts","cortex + medulla")],"Each adrenal gland weighs about as much as a grape.",[ED],["epithelial_tissue","nervous_tissue"],["hormone_signaling"],mesh="adrenal_glands",sec="17.6",kn=EK,mol=["adrenaline","cortisol"])
O("pineal_gland","Pineal gland","structure",0.008,"A tiny pinecone-shaped gland that releases melatonin in the dark.","It helps tell your body when it's night.","It is regulated by light signals through the suprachiasmatic nucleus.","Melatonin synthesis from serotonin by AANAT, peaking at night; calcifies with age.",[("Size","≈ 5-8 mm"),("Hormone","melatonin")],"Descartes proposed it as the seat of the soul.",[ED,"brain"],["nervous_tissue"],["hormone_signaling"],hs=("brain",(0.0,0.0,-0.03),"Pineal gland"),sec="17.7",kn=("sleep_circadian",),mol=["melatonin"])
# Lymph
LY="lymphatic_immune_system"; IM=("immune_system",)
O("spleen","Spleen","organ",0.12,"An organ that filters blood and stores immune cells.","The spleen removes old red blood cells and helps fight infections.","It has red pulp (filtering) and white pulp (immune cells).","Marginal zone B cells respond to blood-borne encapsulated bacteria; red pulp macrophages recycle iron; stores ≈ 200 mL blood.",[("Length","≈ 12 cm"),("Mass","≈ 150 g")],"A person can live without a spleen but is more vulnerable to some infections.",[LY],["lymphocyte_b","macrophage","connective_tissue_loose"],["immune_response"],mesh="spleen",kn=IM,sec="21.1")
O("thymus","Thymus","organ",0.06,"Where T cells mature; largest in children.","T cells go to school in the thymus, learning to ignore your own body.","It is most active in childhood and shrinks with age.","Positive and negative selection of thymocytes; thymic involution begins in adolescence; AIRE expression enables central tolerance.",[("Peak mass","≈ 30-40 g (puberty)"),("Adult","largely replaced by fat")],"Mostly fat by old age, yet T cells made earlier persist for decades.",[LY],["lymphocyte_t","epithelial_tissue"],["immune_response"],mesh="thymus",kn=IM,sec="21.1")
O("lymph_nodes","Lymph nodes","organ",0.01,"Bean-shaped filters where immune cells meet germs in the fluid.","Lymph nodes swell when you're sick because defender cells multiply there.","Lymph drains through them on its way back to the blood.","Afferent lymph enters via the subcapsular sinus; B-cell follicles and T-cell paracortex organize germinal centers.",[("Number","≈ 600-700"),("Size","≈ 1 cm")],"Swollen glands are usually lymph nodes working.",[LY],["lymphocyte_b","lymphocyte_t","macrophage"],["immune_response"],kn=IM,sec="21.1")
O("lymphatic_vessels","Lymphatic vessels","structure",1.0,"Thin vessels that collect leaked fluid and return it to the blood.","They drain extra fluid from tissues and carry it back toward the heart.","Valves keep lymph flowing one way.","Initial lymphatics (lymphatic capillaries) with overlapping endothelial flaps; ≈ 2-4 L/day returned; thoracic duct drains most of the body.",[("Fluid returned/day","≈ 2-4 L")],"Lymph is also how dietary fats reach the blood after a meal.",[LY],["epithelial_tissue","smooth_muscle_tissue"],["immune_response"],kn=IM,sec="21.1")
# Skin
IN="integumentary_system"
O("skin","Skin","organ",0.003,"The body's largest organ: a waterproof, sensitive, self-renewing covering.","Skin protects you from germs, UV light and water loss, helps control body temperature and lets you feel.","Three layers: epidermis (outer), dermis (middle), hypodermis (fat).","Keratinocyte differentiation produces the stratum corneum; epidermal turnover ≈ 28-40 days; melanocytes, Langerhans cells and Merkel cells reside in the epidermis.",[("Area","≈ 1.7-2 m²"),("Thickness","≈ 0.5-4 mm"),("Mass","≈ 4-5 kg")],"Skin is the heaviest organ of the body, around 15% of body weight.",[IN],["keratinocyte","epithelial_tissue","connective_tissue_loose","adipocyte"],[],mesh="skin",sec="5.1",kn=("skin_integument",))
SK="skin"
for i,t,sc,sm,b,d,e,at,lab,made in [
("epidermis","Epidermis",0.0001,"The thin, outer, waterproof layer of skin.","The outer layer is made of flat dead cells, constantly replaced from below.","Cells are made at the bottom and move upward, flatten, and fill with keratin.","Five layers in thick skin: basale, spinosum, granulosum, lucidum, corneum; no blood vessels.",(0.0,0.0005,0.0),"Epidermis",["keratinocyte","epithelial_tissue"]),
("dermis","Dermis",0.0015,"The thick middle layer with fibers, vessels and nerves.","It gives skin its strength and stretch.","Contains collagen, elastin, blood vessels, nerve endings and glands.","Papillary and reticular layers; fibroblasts produce collagen type I and III.",(0.0,-0.0012,0.0),"Dermis",["connective_tissue_loose","dense_connective_tissue"]),
("hair_follicle","Hair follicle",0.003,"A pocket in the skin that grows a hair.","Each hair grows from a root in a follicle.","A hair has a living bulb at the base and a dead keratin shaft.","Growth cycle: anagen, catagen, telogen; dermal papilla signaling; ≈ 5 million follicles, ≈ 100,000 on scalp.",(0.001,-0.001,0.0),"Hair follicle",["keratinocyte"]),
("sweat_gland","Sweat gland",0.004,"A coiled tube that releases sweat to cool the body.","Sweat evaporates and cools you down.","Eccrine glands cover most of the body; apocrine glands are in armpits.","≈ 2-4 million eccrine glands; sweat is ≈ 99% water with Na+, Cl-; cholinergic sympathetic control.",(-0.001,-0.0025,0.0),"Sweat gland",["epithelial_tissue"]),
("hypodermis","Hypodermis",0.003,"The fatty layer under the skin.","It cushions and insulates.","Made of fat cells and loose tissue.","Subcutaneous adipose tissue stores energy.",(0.0,-0.004,0.0),"Hypodermis",["adipocyte","connective_tissue_loose"]),
]:
    O(i,t,"structure",sc,sm,b,d,e,[("Role",sm.rstrip('.'))],{"epidermis":"The surface layer you see is dead cells.","dermis":"Tattoo ink sits in the dermis, which is why it doesn't wash away.","hair_follicle":"Humans have about as many hair follicles as chimpanzees, but most hairs are fine and short.","sweat_gland":"Humans have more sweat glands than any other primate, helping cooling.","hypodermis":"This layer insulates and stores energy."}[i],[SK],made,[],hs=(SK,at,lab),sec="5.1" if i in("epidermis","dermis","hypodermis") else "5.2",kn=("skin_integument",))
# Reproductive
RP="reproductive_system"
O("testes","Testes","organ",0.045,"The male gonads, making sperm and testosterone.","Testes produce sperm and the hormone testosterone.","They hang outside the body where it is slightly cooler.","Spermatogenesis in seminiferous tubules takes ≈ 64-74 days; Leydig cells produce testosterone under LH.",[("Size","≈ 4.5 cm"),("Sperm made","≈ 10^7-10^8/day")],"Sperm production works best a few degrees below core body temperature.",[RP],["epithelial_tissue","connective_tissue_loose","sperm"],[],sec="27.1",kn=("development_biology",),mol=["testosterone"])
O("ovaries","Ovaries","organ",0.035,"The female gonads, releasing eggs and hormones.","The ovaries store eggs and make estrogen and progesterone.","Each cycle, one follicle usually matures and releases an egg.","Follicular development driven by FSH, ovulation triggered by LH surge; ≈ 1-2 million oocytes at birth, ≈ 400,000 left at puberty, none after menopause.",[("Length","≈ 2-3 cm (about the size of an almond)"),("Eggs at birth","≈ 1-2 million")],"Egg cells are present from before birth.",[RP],["epithelial_tissue","connective_tissue_loose","egg_cell"],["hormone_signaling"],sec="27.2",kn=("development_biology",),mol=["estradiol","progesterone"])
O("uterus","Uterus","organ",0.075,"The muscular organ in which an embryo grows.","The uterus can stretch to hold a growing baby.","Its inner lining thickens each cycle and is shed if no pregnancy occurs.","Myometrium (smooth muscle) and endometrium; oxytocin drives labor contractions; uterine weight rises from ≈ 70 g to ≈ 1 kg in pregnancy.",[("Length","≈ 7 cm long, 5 cm wide (not pregnant)"),("Growth","≈ 10-15× in pregnancy")],"It is one of the strongest muscular organs relative to size during labor.",[RP],["smooth_muscle_tissue","epithelial_tissue"],[],sec="27.2",kn=("development_biology",))
save("body_viscera",S)
